  try {

    // Phi-4 / OpenAI style response
    let text =
      $json.choices?.[0]?.message?.content ||
      $json.message?.content ||
      "";

    // markdown cleanup
    text = text
      .replace(/```json/g, "")
      .replace(/```/g, "")
      .trim();

    // double encoded json handle
    if (typeof text === "string") {
      try {
        return JSON.parse(text);
      } catch {
        return JSON.parse(JSON.parse(text));
      }
    }

    return text;

  } catch (e) {

    return {
      error: "Invalid JSON from model",
      raw: $json
    };

  }
})() }}

