const item = $input.first();

try {

  // binary buffer directly read karo
  const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

  // utf8 string
  let jsonString = buffer.toString('utf8');

  // cleanup
  jsonString = jsonString
    .replace(/^\uFEFF/, '')
    .trim();

  // debug
  console.log(jsonString);

  // parse
  const parsedData = JSON.parse(jsonString);

  // extra binaries preserve
  const binaries = {};

  for (const key of Object.keys(item.binary || {})) {
    if (key !== 'data') {
      binaries[key] = item.binary[key];
    }
  }

  return [
    {
      json: parsedData,
      binary: binaries,
    }
  ];

} catch (error) {

  return [
    {
      json: {
        success: false,
        error: error.message,
      }
    }
  ];

}
